import React, { useState, useEffect } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";

const SubNavigation: React.FC = () => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.submenu;

  // show scrool to top button 
    const [showButton, setShowButton] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const scrollTop = window.scrollY || document.documentElement.scrollTop;
      setShowButton(scrollTop > 0); // Solo mostrar si no está completamente arriba
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // if (typeof window === "undefined" || !showButton) return null;

  const handleScroll = (id: string) => {
  const section = document.getElementById(id);
  if (section) {
    section.scrollIntoView({ behavior: "smooth" });
    setIsOpen(false); // opcional: cerrar el menú móvil al hacer clic
  }
};


  return (
    <>
      <nav className="fixed h-[3.75rem] w-full px-0 text-Tofu z-40">
        <div className="flex justify-between items-center w-full sm:px-[3.75rem] h-full bg-black/20 backdrop-blur-xl">
          {/* Desktop Menu */}
          <div className="hidden md:flex w-full justify-center">
            <ul className="flex space-x-6">
              {menuItems.map((item, index) => (
                <li key={index}>
                  <a
                    onClick={() => handleScroll(item)}
                    className="text-primary hover:text-secondary cursor-pointer"
                  >
                    {t(`submenu.${item}`)}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Mobile Toggle Button */}
          <button onClick={() => setIsOpen(!isOpen)} className="md:hidden flex justify-between px-4 w-full">
            <span>{t("submenu.title")}</span>
            {isOpen ? <img src="../up.svg" alt="Close menu" /> : <img src="../down.svg" alt="Open menu" />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isOpen && (
          <ul className="absolute top-full left-0 w-full bg-black/10 !backdrop-blur-md z-40 md:hidden shadow-lg">
            {menuItems.map((item, index) => (
              <li
                key={index}
                className={`p-4 ${index < menuItems.length - 1 ? 'border-b border-white/20' : ''}`}
              >
                <a
                  onClick={() => handleScroll(item)}
                  className="text-accent hover:text-secondary block"
                >
                  {t(`submenu.${item}`)}
                </a>
              </li>
            ))}
          </ul>
        )}
      </nav>
      {typeof window !== "undefined" && showButton && (
        <button
          onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
          className="fixed bottom-12 right-4 px-6 py-2 bg-Trooper text-white rounded-full shadow-lg hover:bg-Kayaking transition z-40"
          aria-label="Back to top"
        >
          {t("submenu.backToTop")}
        </button>
      )} 
    </>

  );
}

export default SubNavigation;