import * as React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import { IndustryItem } from "../interfaces";
import data from "../data/data.json";

const IndustryGrid: React.FC = () => {
  const { t } = useTranslation();
  const sections = t("industry.sections", {
    returnObjects: true,
  }) as IndustryItem[];

  return (
    <>
      {sections.map((section: any, index: number) => {
        const isEven = index % 2 === 0;
        const imageData = images[section.image] || {};
        const isLast = index === sections.length - 1;
        return (
          <section
            key={section.name || index}
            id={data.submenu[index]}
            className={`space-y-32 py-16 pt-32 -mb-16 ${
              !isLast ? "border-b border-Tofu/20" : ""
            }`}
          >
            <div
              className={`flex flex-col sm:flex-row ${
                isEven ? "" : "sm:flex-row-reverse"
              } gap-12 sm:gap-24`}
            >
              {/* Image */}
              <div className="w-[calc(100%+40px)] sm:w-3/4 -ml-[20px] sm:-ml-0">
                <img
                  src={imageData.src}
                  alt={imageData.alt || section.name}
                  className="w-full h-auto"
                />
              </div>

              {/* Content */}
              <div className="w-full sm:w-1/4 text-Tofu space-y-6">
                {/* Title */}
                <h2 className="head-3 uppercase">{section.name}</h2>

                {/* Intro Paragraphs */}
                {section.intro?.map((p: { item: string }, i: number) => (
                  <p key={i} className="body-3">
                    {p.item}
                  </p>
                ))}

                {/* Applications List */}
                {section.info?.applications?.length > 0 && (
                  <>
                    <h4 className="head-7 mt-6">Applications</h4>
                    <ul className="list-disc list-outside ml-6 space-y-2 ">
                      {section.info.applications.map(
                        (app: { item: string }, i: number) => (
                          <li
                            key={i}
                            className="body-4"
                            dangerouslySetInnerHTML={{ __html: app.item }}
                          />
                        )
                      )}
                    </ul>
                  </>
                )}

                {/* Key Benefits (no bullets, estilo título/párrafo) */}
                {section.info?.keyBenefits?.length > 0 && (
                  <>
                    <h4 className="head-7 mt-6">Key Benefits</h4>
                    <ul className="list-none space-y-4 mt-2">
                      {section.info.keyBenefits.map(
                        (benefit: { item: string }, i: number) => (
                          <li
                            key={i}
                            className="body-4"
                            dangerouslySetInnerHTML={{ __html: benefit.item }}
                          />
                        )
                      )}
                    </ul>
                  </>
                )}
              </div>
            </div>
          </section>
        );
      })}
    </>
  );
};

export default IndustryGrid;
